"""Random in-domain generator for CrossCheck replay tests."""
import random
import string


def gen_topology(rng, max_nodes=8, max_links=None, force_external=None):
    n = rng.randint(1, max_nodes)
    ids = rng.sample(range(0, 65536), n)
    names = []
    alphabet = string.ascii_letters
    rest = string.ascii_letters + string.digits
    while len(names) < n:
        name = rng.choice(alphabet) + ''.join(rng.choice(rest) for _ in range(rng.randint(0, 11)))
        if name not in names:
            names.append(name)
    nodes = []
    for i in range(n):
        nodes.append({"id": ids[i], "name": names[i], "external_capacity": rng.randint(0, 10 ** 9)})
    # links with degree bound 8
    if max_links is None:
        max_links = 2 * n
    links = []
    seen = set()
    degree = {node["id"]: 0 for node in nodes}
    attempts = 0
    while len(links) < min(max_links, n * 4) and attempts < 400:
        attempts += 1
        a, b = rng.sample(nodes, 2)
        if degree[a["id"]] >= 8 or degree[b["id"]] >= 8:
            continue
        key = (min(a["id"], b["id"]), max(a["id"], b["id"]))
        if key in seen:
            continue
        seen.add(key)
        degree[a["id"]] += 1
        degree[b["id"]] += 1
        links.append({"source": a["id"], "target": b["id"], "capacity": rng.randint(0, 10 ** 9)})
    count = min(len(names), rng.randint(0, min(16, n)))
    if force_external is not None:
        count = force_external
    external = rng.sample(names, count)
    return {"nodes": nodes, "links": links, "external_nodes": external}


def simple_path(rng, adjacency, source, target, max_vertices=33):
    """Random simple path from source to target as a name list."""
    if source == target:
        return None
    path = [source]
    used = {source}

    def walk(node):
        if node == target and len(path) >= 2:
            return True
        neighbours = adjacency.get(node, [])
        order = list(neighbours)
        rng.shuffle(order)
        for nxt in order:
            if nxt in used:
                continue
            if len(path) >= max_vertices:
                continue
            used.add(nxt)
            path.append(nxt)
            if walk(nxt):
                return True
            used.discard(nxt)
            path.pop()
        return False

    if not walk(source):
        return None
    return path


def gen_routes(rng, topology):
    names = topology["external_nodes"]
    nodes = {node["name"]: node["id"] for node in topology["nodes"]}
    adjacency = {}
    for node in topology["nodes"]:
        adjacency[node["id"]] = []
    for link in topology["links"]:
        adjacency[link["source"]].append(link["target"])
        adjacency[link["target"]].append(link["source"])
    id_name = {node["id"]: node["name"] for node in topology["nodes"]}
    plan = {}
    hops = 0
    for source in names:
        bundle = {}
        for target in names:
            if source == target:
                continue
            entries = []
            count = rng.randint(1, 4)
            weights = [rng.randint(1, 1000) for _ in range(count)]
            total = sum(weights)
            weights = [max(1, (w * 1000) // total) for w in weights]
            weights[-1] = 1000 - sum(weights[:-1])
            if weights[-1] <= 0:
                weights = [1000 // count] * count
                weights[-1] = 1000 - sum(weights[:-1])
            for _ in range(count):
                path = simple_path(rng, adjacency, nodes[source], nodes[target])
                if path is None:
                    break
                if hops + len(path) > 4000:
                    break
                hops += len(path)
                entries.append({"path": [id_name[i] for i in path], "weight": weights[len(entries)]})
            if entries:
                total = sum(e["weight"] for e in entries)
                if total != 1000:
                    diff = 1000 - total
                    entries[0]["weight"] += diff
                    if entries[0]["weight"] <= 0:
                        return None
                bundle[target] = entries
        if len(bundle) != len([n for n in names if n != source]):
            return None
        plan[source] = bundle
    return plan


def gen_settings(rng, **override):
    settings = {
        "trials": rng.randint(1, 32),
        "epsilon": rng.choice([0, 1, 1000, 25000, 250000, rng.randint(0, 250000)]),
        "seed": rng.randint(0, 2 ** 32 - 1),
        "cutoff": [rng.randint(0, 5 * 10 ** 9), rng.randint(1, 10 ** 9)],
        "bias": rng.randint(0, 1000000),
        "tau": rng.randint(0, 1000000),
        "gamma": [rng.randint(0, 10 ** 9), rng.randint(1, 10 ** 9)],
        "cache_slots": rng.randint(0, 8),
    }
    settings.update(override)
    return settings
